/* Copyright(c) 2026  CatchChallenger project
 *
 * RTL8192XB PHY / RF / tx-power tables.
 *
 * Generated from the Realtek "g6" hwimg raw-data facts for the RTL8192XB
 * (2.4 GHz-only 2x2 802.11ax) and re-expressed in the mainline rtw89 table
 * form.  The register/value facts and the txpwr limit numbers are hardware
 * facts (not copyrightable); the layout matches the mainline rtw89 driver so
 * the generic phy loader consumes them unchanged.  The conversion was proven
 * by reproducing the mainline RTL8852C tables from the vendor 8852C facts of
 * the same generation (see dev/x411axf scratch converter).
 *
 * This chip is 2.4 GHz only: the 5 GHz / 6 GHz limit pointers in the rfe
 * parms are NULL (never dereferenced -- the driver only reads a band's limit
 * table while tuned to that band, and support_bands excludes 5/6 GHz).
 */

#include "phy.h"
#include "reg.h"
#include "rtw8192xb_table.h"

/* RFE-type-50 (iFEM, PON/ONU board) BB program, register/value facts
 * reverse-engineered from the stock firmware of this product: the stock
 * driver does NOT use its built-in generic BB image on this board -- it
 * runtime-loads the board BB program (boot log: "rtw_load_phy_file_path(1)
 * /etc/conf/rtl8192xbe/RFE50/" + PHY_REG + the PON_2G overlay, applied in
 * that order), same mechanism already proven for the radioA/B program.
 * The board program is a newer BB parameter drop than the generic image
 * (BB version stamp 0xF4: board 0x47/2024-06-05 vs generic 0x30/2022-07-15)
 * with board-specific AGC/RF-path/TSSI settings; the PON_2G overlay adds the
 * ONU txagc bounds / pwsf / txgapk-PSD seeds (0x81xx/0x82xx).
 * Layout: single RFE50 headline + flat write list in stock apply order.
 * Trailing 0xF0/0xF4/0xF8 writes are the BB system-info stamp registers
 * (real BB CRs; only 0xF9-0xFE would be delay tokens). */

