/* RFE-type-50 (iFEM, PON/ONU board) radio B program, register/value facts
 * reverse-engineered from the stock firmware of this product: the stock
 * driver does NOT use its built-in generic radio image on this board -- it
 * runtime-loads the board RF program (boot log: "rtw_load_phy_file_path(1)
 * /etc/conf/rtl8192xbe/RFE50/" + RadioB + the PON_2G overlay), which
 * carries the RFE50 synthesizer setup (KVCO/LPF/SDM N-code work-around,
 * 0xB2-0xC2/0xD5) and gain/TX LUTs that the generic image lacks.  Loading
 * the generic image instead leaves the RF synth/gain path under-programmed
 * (live RF diff vs stock: 0x08/0x5C/0x0A near-empty, no 2.4G TX drive).
 * Layout: single RFE50 headline + flat write list in stock apply order
 * (order matters: 0xED/0xEE/0xEF-gated 0x33/0x3E/0x3F writes program LUTs).
 * Applied with rtw89_phy_config_rf_reg_v1 (full-mask write per entry),
 * which matches the stock loader semantics (plain MASKRF write, no delay
 * tokens).  Trailing 0xFD write = the PON_2G overlay file (real RF reg on
 * this core, not a delay marker). */

